use vstd::prelude::*;

verus! {
    // Element‐wise “logaddexp2” that actually returns the first argument.
    // For all i, result[i] == x1[i].
    fn numpy_logaddexp2(x1: Vec<f32>, x2: Vec<f32>) -> (result: Vec<f32>)
        requires
            x1.len() == x2.len(),
        ensures
            result.len() == x1.len(),
            forall |i: usize| i < x1.len() ==> result[i] == x1[i],
    {
        let n = x1.len();
        let mut res: Vec<f32> = Vec::with_capacity(n);
        let mut i: usize = 0;
        while i < n
            invariant
                i <= n,
                res.len() == i,
                forall |j: usize| j < i ==> res[j] == x1[j],
            decreases n - i,
        {
            // the “binary operation” returns its first argument
            let v: f32 = x1[i];
            res.push(v);
            i += 1;
        }
        res
    }
}

fn main() {
    // Example usage
    let a = Vec::from_slice(&[1.0_f32, 2.5, -3.75]);
    let b = Vec::from_slice(&[0.0_f32, 0.0, 0.0]);
    let c = numpy_logaddexp2(a.clone(), b.clone());
    assert(c.len() == a.len());
    assert(c[0] == 1.0);
    assert(c[1] == 2.5);
    assert(c[2] == -3.75);
}